export function Milestone({
  name = "{{name}}",
  date = "{{date}}",
  progress = {{progress}},
  reached = {{reached}},
  accent = "{{accent}}",
}) {
  return (
    <figure aria-label={"Milestone: " + name + ", " + date} style={{ margin: 0, maxWidth: 480, padding: "18px 20px", borderRadius: 12, background: "#FAF7F2", border: "1px solid #24143022", boxSizing: "border-box", font: "14px/1.4 system-ui, sans-serif", color: "#241430" }}>
      <svg style={{ display: "block", width: "100%", marginBottom: 14 }} viewBox="0 0 100 20" preserveAspectRatio="none" width="100%" height="20" aria-hidden="true">
        <line x1="2" y1="10" x2="98" y2="10" stroke="#24143033" strokeWidth="2" />
        <circle cx={progress} cy="10" r="5" fill={accent} stroke="#241430" strokeWidth="1" />
      </svg>
      <figcaption style={{ display: "flex", flexWrap: "wrap", alignItems: "center", gap: "4px 12px" }}>
        <h3 style={{ margin: 0, fontSize: 15, fontWeight: 700, flexBasis: "100%" }}>{name}</h3>
        <p style={{ margin: 0, fontSize: 13, color: "#241430b3" }}>{date}</p>
        {reached ? (
          <span style={{ marginLeft: "auto", display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12, fontWeight: 600, padding: "4px 9px", borderRadius: 999, background: "color-mix(in srgb, #A8E6C1 45%, #FAF7F2)", color: "#205c37" }}>
            <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><circle cx="8" cy="8" r="6.3" /><path d="M5.3 8.2 7 9.9l3.6-4" /></svg>
            Reached
          </span>
        ) : (
          <span style={{ marginLeft: "auto", display: "inline-flex", alignItems: "center", gap: 5, fontSize: 12, fontWeight: 600, padding: "4px 9px", borderRadius: 999, background: "color-mix(in srgb, #D9C8F0 45%, #FAF7F2)", color: "#4a3a68" }}>
            <svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.4"><path d="M4 14V2" /><path d="M4 3h8l-2 2.5L12 8H4" /></svg>
            Upcoming
          </span>
        )}
      </figcaption>
    </figure>
  );
}
